{
  "decision-select-noncompeting-replication-sites": "SELECT a.shop_code AS first_shop, b.shop_code AS second_shop, a.basket_gain + b.basket_gain AS forecast_baskets, a.spend_cents + b.spend_cents AS setup_cents FROM shop_bid AS a JOIN shop_bid AS b ON a.shop_code COLLATE BINARY < b.shop_code AND a.zone_code <> b.zone_code WHERE a.spend_cents + b.spend_cents <= 10000 ORDER BY forecast_baskets DESC, setup_cents ASC, first_shop COLLATE BINARY ASC, second_shop COLLATE BINARY ASC LIMIT 1",
  "decision-select-outage-resilient-charging-layout": "SELECT m.source_id, b.layout_code, COALESCE(SUM(f.feed_kw) - MAX(f.feed_kw), 0) AS guaranteed_kw, b.fee_cents FROM site_memo AS m JOIN layout_bid AS b ON b.fee_cents <= m.ceiling_cents LEFT JOIN circuit_feed AS f ON f.layout_code = b.layout_code GROUP BY m.source_id, b.layout_code, b.fee_cents ORDER BY guaranteed_kw DESC, b.fee_cents ASC, b.layout_code COLLATE BINARY ASC LIMIT 1",
  "decision-select-overlap-aware-purge-runs": "SELECT a.run_code AS first_run, b.run_code AS second_run, (SELECT COUNT(DISTINCT t.entry_code) FROM run_targets AS t WHERE t.run_code IN (a.run_code, b.run_code)) AS entries_cleared, a.run_minutes + b.run_minutes AS total_minutes FROM purge_runs AS a JOIN purge_runs AS b ON a.run_code COLLATE BINARY < b.run_code WHERE a.run_minutes + b.run_minutes <= 8 ORDER BY entries_cleared DESC, total_minutes ASC, first_run COLLATE BINARY ASC, second_run COLLATE BINARY ASC LIMIT 1",
  "decision-separate-monument-drift-from-datum-reset": "WITH corrected AS (SELECT m.sector, m.point_id, m.visit_no, m.east_mm - c.east_mm AS corrected_mm FROM monument_reading AS m JOIN control_reading AS c ON c.sector = m.sector AND c.visit_no = m.visit_no WHERE m.visit_no IN (1, 2) AND m.east_mm IS NOT NULL AND c.east_mm IS NOT NULL) SELECT a.sector, COUNT(*) AS paired_count, SUM(b.corrected_mm - a.corrected_mm) AS net_east_mm FROM corrected AS a JOIN corrected AS b ON b.sector = a.sector AND b.point_id = a.point_id WHERE a.visit_no = 1 AND b.visit_no = 2 GROUP BY a.sector ORDER BY a.sector COLLATE BINARY"
}
